CREATE TABLE cloud_workspace(id text PRIMARY KEY, name text NOT NULL, owner_account_id text NOT NULL);
CREATE TABLE account(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES cloud_workspace(id) DEFERRABLE INITIALLY DEFERRED, login text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('owner','employee')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE cloud_workspace ADD CONSTRAINT workspace_owner_fk FOREIGN KEY(owner_account_id) REFERENCES account(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE workspace_state(workspace_id text PRIMARY KEY REFERENCES cloud_workspace(id), revision bigint NOT NULL DEFAULT 0, data jsonb NOT NULL, history jsonb NOT NULL);
CREATE TABLE project(workspace_id text NOT NULL REFERENCES cloud_workspace(id),id text NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE person(workspace_id text NOT NULL REFERENCES cloud_workspace(id),id text NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE trade(workspace_id text NOT NULL, id text NOT NULL, project_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,project_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE task(workspace_id text NOT NULL,id text NOT NULL,project_id text NOT NULL,trade_id text NOT NULL,start_date date NOT NULL,end_date date NOT NULL CHECK(end_date>=start_date),payload jsonb NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,trade_id) REFERENCES trade(workspace_id,project_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE purchase(workspace_id text NOT NULL,id text NOT NULL,project_id text NOT NULL,task_id text, payload jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(workspace_id,project_id,task_id) REFERENCES task(workspace_id,project_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE memo(workspace_id text NOT NULL,id text NOT NULL,project_id text NOT NULL,task_id text,payload jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(workspace_id,project_id,task_id) REFERENCES task(workspace_id,project_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE assignment(workspace_id text NOT NULL,scope_kind text NOT NULL CHECK(scope_kind IN ('project','trade','task')),scope_id text NOT NULL,project_id text NOT NULL,person_id text NOT NULL,PRIMARY KEY(workspace_id,scope_kind,scope_id,person_id),FOREIGN KEY(workspace_id,person_id) REFERENCES person(workspace_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE person_private(workspace_id text NOT NULL,person_id text NOT NULL,sealed jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,person_id),FOREIGN KEY(workspace_id,person_id) REFERENCES person(workspace_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE project_permission(workspace_id text NOT NULL,project_id text NOT NULL,account_id text NOT NULL REFERENCES account(id),can_write boolean NOT NULL DEFAULT false,PRIMARY KEY(workspace_id,project_id,account_id),FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE auth_session(token_hash text PRIMARY KEY,account_id text NOT NULL REFERENCES account(id),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX auth_session_expiry ON auth_session(expires_at);
CREATE TABLE login_limit(bucket text PRIMARY KEY,attempts integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE audit_event(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES cloud_workspace(id),actor_id text NOT NULL REFERENCES account(id),action text NOT NULL,revision bigint,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_preview(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES cloud_workspace(id),actor_id text NOT NULL REFERENCES account(id),base_revision bigint NOT NULL,hash text NOT NULL,payload jsonb NOT NULL,expires_at timestamptz NOT NULL,consumed boolean NOT NULL DEFAULT false);
CREATE TABLE imported_archive(workspace_id text NOT NULL REFERENCES cloud_workspace(id),hash text NOT NULL,actor_id text NOT NULL REFERENCES account(id),revision bigint NOT NULL,PRIMARY KEY(workspace_id,hash));
